import{_ as t,c as o,o as d,a7 as a}from"./chunks/framework.BxaL7nSC.js";const p=JSON.parse('{"title":"Security Migration Notes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security-migration.md","filePath":"guide/security-migration.md"}'),r={name:"guide/security-migration.md"};function i(n,e,s,l,c,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="security-migration-notes" tabindex="-1">Security Migration Notes <a class="header-anchor" href="#security-migration-notes" aria-label="Permalink to “Security Migration Notes”">​</a></h1><p>Recent releases make trust boundaries explicit and fail closed where request metadata can affect identity, rate limits, telemetry, or browser access.</p><h2 id="forwarded-headers" tabindex="-1">Forwarded Headers <a class="header-anchor" href="#forwarded-headers" aria-label="Permalink to “Forwarded Headers”">​</a></h2><p>Forwarding headers are now ignored by default. Configure the CIDRs of proxies that connect directly to Ada; do not list arbitrary client networks. The proxy must overwrite incoming forwarding headers rather than append values supplied by the client.</p><table tabindex="0"><thead><tr><th>Component</th><th>Secure configuration</th><th>Compatibility option</th></tr></thead><tbody><tr><td><a href="./middleware/log.html">Request log</a></td><td><code>log.WithRealIP(proxy.TrustedRealIP(cidrs...))</code></td><td><code>log.WithRealIP(proxy.UnsafeRealIP)</code></td></tr><tr><td><a href="./middleware/ratelimit.html">Rate limit</a></td><td><code>ratelimit.LimitByKey(n, w, proxy.TrustedRealIP(cidrs...))</code></td><td><code>ratelimit.LimitByKey(n, w, proxy.UnsafeRealIP)</code></td></tr><tr><td><a href="./middleware/telemetry.html">Telemetry</a></td><td><code>telemetry.WithClientIP(proxy.TrustedRealIP(cidrs...))</code></td><td><code>telemetry.WithClientIP(proxy.UnsafeRealIP)</code></td></tr><tr><td><a href="./middleware/auth.html#header-proxy-strategy">Header auth</a></td><td><code>header.WithTrustedProxies(cidrs...)</code>, <code>WithSharedSecret(...)</code>, or both</td><td><code>header.WithUnsafeTrustAll()</code></td></tr><tr><td><a href="./middleware/auth.html#magic-link-strategy">Magic link</a></td><td><code>magiclink.WithVerifyBaseURL(origin)</code> or <code>WithTrustedProxies(cidrs...)</code></td><td><code>magiclink.WithUnsafeRequestOrigin()</code></td></tr><tr><td><a href="./middleware/auth.html#oauth2-oidc-strategy">OAuth2</a></td><td><code>CallbackBaseURL</code> or <code>TrustedProxies</code></td><td><code>UnsafeTrustAllForwardedHeaders</code></td></tr></tbody></table><p>The compatibility options restore legacy trust-all behavior. They are unsafe when untrusted clients can connect directly and should be temporary migration tools, not the default deployment configuration.</p><h2 id="client-address-resolution-moved" tabindex="-1">Client Address Resolution Moved <a class="header-anchor" href="#client-address-resolution-moved" aria-label="Permalink to “Client Address Resolution Moved”">​</a></h2><p><code>log</code>, <code>ratelimit</code>, and <code>telemetry</code> no longer carry a trusted-proxy policy and no longer depend on the proxy package. Deriving a client address across a proxy boundary is a deployment decision, and three copies of that decision drift apart in exactly the direction an attacker wants. There is now one implementation, in <code>github.com/rakunlabs/ada/middleware/auth/proxy</code>, injected where it is needed.</p><table tabindex="0"><thead><tr><th>Removed</th><th>Replacement</th></tr></thead><tbody><tr><td><code>log.WithTrustedProxies(cidrs...)</code></td><td><code>log.WithRealIP(proxy.TrustedRealIP(cidrs...))</code></td></tr><tr><td><code>log.WithUnsafeProxyHeaders()</code></td><td><code>log.WithRealIP(proxy.UnsafeRealIP)</code></td></tr><tr><td><code>log.TrustedRealIP(cidrs...)</code></td><td><code>proxy.TrustedRealIP(cidrs...)</code></td></tr><tr><td><code>log.UnsafeRealIP</code></td><td><code>proxy.UnsafeRealIP</code></td></tr><tr><td><code>ratelimit.LimitByRealIP(n, w, WithTrustedProxies(cidrs...))</code></td><td><code>ratelimit.LimitByKey(n, w, proxy.TrustedRealIP(cidrs...))</code></td></tr><tr><td><code>ratelimit.LimitByRealIP(n, w)</code></td><td><code>ratelimit.LimitByIP(n, w)</code></td></tr><tr><td><code>ratelimit.LimitByRealIPUnsafe(n, w)</code></td><td><code>ratelimit.LimitByKey(n, w, proxy.UnsafeRealIP)</code></td></tr><tr><td><code>ratelimit.KeyByRealIP</code></td><td><code>ratelimit.KeyByIP</code></td></tr><tr><td><code>ratelimit.KeyByRealIPWithTrustedProxies(cidrs...)</code></td><td><code>proxy.TrustedRealIP(cidrs...)</code></td></tr><tr><td><code>ratelimit.KeyByRealIPUnsafe</code></td><td><code>proxy.UnsafeRealIP</code></td></tr><tr><td><code>telemetry.WithTrustedProxies(cidrs...)</code></td><td><code>telemetry.WithClientIP(proxy.TrustedRealIP(cidrs...))</code></td></tr><tr><td><code>telemetry.WithUnsafeProxyHeaders()</code></td><td><code>telemetry.WithClientIP(proxy.UnsafeRealIP)</code></td></tr><tr><td><code>telemetry.TrustedRequestTraceAttrs(cidrs...)</code></td><td><code>telemetry.WithClientIP(proxy.TrustedRealIP(cidrs...))</code></td></tr><tr><td><code>telemetry.UnsafeRequestTraceAttrs</code></td><td><code>telemetry.WithClientIP(proxy.UnsafeRealIP)</code></td></tr><tr><td><code>guard.ClientIP(r, []*net.IPNet)</code></td><td><code>guard.ClientIP(r, proxy.Policy)</code>, built with <code>proxy.MustNew(cidrs...)</code></td></tr></tbody></table><p>The package also moved: <code>github.com/rakunlabs/ada/utils/proxy</code> is now <code>github.com/rakunlabs/ada/middleware/auth/proxy</code>, and is no longer a separate module.</p><p>Defaults are unchanged. Code that never configured trusted proxies keeps logging, limiting, and tracing by the immediate peer.</p><h2 id="auth-responses-and-mfa" tabindex="-1">Auth Responses And MFA <a class="header-anchor" href="#auth-responses-and-mfa" aria-label="Permalink to “Auth Responses And MFA”">​</a></h2><ul><li>Header auth rejects login when no trust option is configured.</li><li>Magic-link sending fails with <code>verify_origin_unavailable</code> when no fixed public origin or matching trusted-proxy policy is available.</li><li><code>POST /login/refresh</code> returns the refreshed identity only. The opaque session ID remains in its <code>HttpOnly</code> cookie and is no longer exposed as <code>session_id</code>.</li><li><code>WithIssuer</code> plus <code>WithSecondFactor</code> requires <code>WithPendingIssuer</code>. The pending issuer must implement <code>issuer.AtomicUpdater</code>, report atomic updates, and expire no later than <code>MFA.TTL</code>.</li><li>Auth strategies now enforce their existing request-body caps instead of silently truncating oversized input and reporting a parse error. Local, LDAP, magic-link and OAuth2 requests are capped at 64 KiB, TOTP at 16 KiB, and passkey at 128 KiB; exceeding a cap answers <code>413 body_too_large</code>.</li><li>OAuth2 discovery, token, UserInfo and JWKS responses retain their 1 MiB caps, but an oversized identity-provider response is now reported as an upstream size failure rather than malformed truncated JSON.</li><li>A failed JWKS refresh uses a short retry backoff instead of blocking refresh for the full successful-fetch cooldown. A JWT without <code>kid</code> is rejected immediately when the key set contains multiple usable keys.</li></ul><h2 id="request-and-browser-defaults" tabindex="-1">Request And Browser Defaults <a class="header-anchor" href="#request-and-browser-defaults" aria-label="Permalink to “Request And Browser Defaults”">​</a></h2><ul><li><p><strong>There is no default request body size limit.</strong><a href="./binding.html#request-body-limit">Binding</a> previously capped the total body at 1 MiB; <code>bind.DefaultBodyLimit</code> is now <code>0</code> (disabled). Nothing bounds a request body until you impose a limit, and what an unbounded request exhausts depends on the content type:</p><ul><li>JSON, XML and URL-encoded bodies are read <strong>entirely into memory</strong>, so an unbounded request is an unbounded allocation.</li><li>Multipart bodies buffer up to <code>bind.DefaultMultipartFormMaxMemory</code> (plus the 10 MiB Go reserves for non-file parts) and then <strong>spool the remainder to temporary files on disk</strong>, so an unbounded upload exhausts disk rather than memory. Those temporary files are cleaned up, but not before the request finishes.</li></ul><p>Add the <a href="./middleware/bodylimit.html">body-limit middleware</a> — <code>mux.Use(bodylimit.Middleware(2 &lt;&lt; 20))</code> — or enforce a body size limit at your reverse proxy. If routes need different limits, use non-overlapping groups or skip those routes in the global limiter and limit them separately. A nested limit cannot raise an outer middleware or proxy limit; the smallest limit remains effective.</p></li><li><p>The old default was removed because it protected the wrong thing: it only applied to requests that went through <code>bind</code>, never to handlers reading <code>r.Body</code> directly, and it rejected oversized bodies as a redacted <code>500</code>. Exceeding a limit now answers <code>413 Content Too Large</code> with a message naming the limit. Clients and monitoring that keyed on the <code>500</code> must be updated.</p></li><li><p><code>bind.WithBodyLimit(n)</code> still sets a per-bind limit, and <code>bind.WithBodyLimit(0)</code> still means &quot;no limit&quot; — it is now simply the default rather than an opt-out.</p></li><li><p>The query separator now applies only to slices of scalar values. Scalar and JSON-valued fields preserve commas, so <code>?name=Doe,%20John</code> binds as <code>&quot;Doe, John&quot;</code> instead of silently becoming <code>&quot;Doe&quot;</code>. Malformed query escapes now return a binding error instead of disappearing from <code>URL.Query()</code>.</p></li><li><p>Removing the 1 MiB cap makes <code>bind.DefaultMultipartFormMaxMemory</code> (32 MiB) reachable again; it was previously capped away by the total body limit. Note that it is a memory/disk threshold, <strong>not</strong> a size limit — it never rejects a request. Only the body-limit middleware or your proxy can do that.</p></li><li><p><a href="./middleware/cors.html#allowheaders">CORS</a> no longer reflects requested headers when <code>AllowHeaders</code> is empty. Explicitly allow the required headers.</p></li><li><p>Credentialed CORS requires explicit origins. The wildcard-origin combination is rejected unless <code>UnsafeWildcardOriginWithAllowCredentials</code> is enabled.</p></li><li><p><a href="./routing.html#wildcard-routes">Wildcard helpers</a> do not register the slashless base path: <code>HandleFuncWildcard(&quot;/assets&quot;, ...)</code> matches <code>/assets/</code> (with an empty wildcard value) and descendants, but not exact <code>/assets</code>.</p></li><li><p>Empty segments never start a capture: <code>/assets//x</code> is a 404 where ServeMux would clean-and-redirect it, because Ada applies no path cleaning. Once a greedy capture has started, its tail is kept verbatim, <code>//</code> included.</p></li><li><p>A trailing slash after a greedy (<code>&quot;/files/{p...}/&quot;</code>) now panics at registration instead of silently matching a single segment plus <code>/</code>.</p></li><li><p>The default error handler no longer echoes arbitrary error text. A <code>*ada.HTTPError</code> with a 4xx/5xx status still sends its own message, and an error you deliberately answer 4xx with still sends its text; any other error resolved to a 5xx now sends the generic status text and logs the real error with <code>slog</code> at Error level. Set a <code>Mux.ErrorHandler</code> to choose a different policy. Text wrapped <em>around</em> an <code>HTTPError</code> is no longer published.</p></li><li><p><code>ada.NewHTTPError(code, ...)</code> only sets the response status when <code>code</code> is an error status. A 2xx/3xx/zero <code>Code</code> on a returned error is now promoted to 500 instead of answering success with an error body.</p></li><li><p>Clearing <code>ada.DefaultErrHandler</code> no longer yields <code>200</code> with an empty body; the normalised status is written as a plain-text response.</p></li><li><p><code>Context.Bind</code> accepts bind options — use <code>c.Bind(&amp;obj, bind.WithBodyLimit(n))</code> to cap a single endpoint more tightly than its route&#39;s body-limit middleware.</p></li><li><p><a href="./routing.html#http-methods">Route selection</a> is method-aware, so a path that matches a node registered under another method no longer ends the search: requests that used to answer <code>405</code> now reach the parameterised or wildcard route that can serve them. Valid method tokens are normalized to uppercase, so <code>HandleWithMethod(&quot;get&quot;, ...)</code> registers <code>GET</code> instead of an unreachable lowercase route. Invalid RFC 9110 tokens still panic at setup; <code>&quot;&quot;</code> remains the <code>Handle</code>/<code>HandleFunc</code> catch-all.</p></li><li><p>A <a href="./routing.html#route-groups"><code>Group</code></a> inherits its parent&#39;s <code>NotFound</code>, <code>MethodNotAllowed</code> and <code>Use</code> even when they are configured after the group is created. Previously the group froze a copy of the parent at creation time and claimed its prefix, so a later root <code>NotFound</code> or <code>Use</code> never applied below that prefix. A group that sets its own still wins, for that behavior only.</p></li></ul><h2 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to “Rate Limiting”">​</a></h2><ul><li>Under the default fail-closed policy, downstream responses are buffered until the attempt is persisted. A response larger than <code>ResponseBufferLimit</code> (1 MiB by default) now answers <code>500 response_too_large</code> and reaches <code>OnError</code>; it is no longer misreported as <code>503 rate_limit_unavailable</code>. The attempt remains counted because the protected handler ran and produced a countable status.</li><li>Fail-closed buffering cannot support SSE, WebSocket upgrades, or other streaming responses. Flush attempts now return <code>ErrStreamingUnsupported</code> and reach <code>OnError</code>. Use fail-open policy or scope the limiter to a separate, non-streaming authentication request when streaming is required.</li><li><code>NewMemoryStore</code> no longer evicts a live bucket to make room, because doing so resets that key&#39;s counter. It reclaims expired state; if capacity is full of live state, the store returns an error and <code>ErrorPolicy</code> decides whether to fail closed or open. Capacity bounds active bucket keys, not total memory: buckets retain each live attempt timestamp and in-flight reservation. A hard threshold bounds those records for a normally governed key; a soft-only limiter does not, even when <code>BackoffMax</code> is set.</li><li>Configurable limiter construction now panics when both <code>SoftThreshold</code> and <code>HardThreshold</code> are zero. Omit the middleware to disable enforcement.</li><li><code>LimitAll</code>, <code>LimitByIP</code>, and related simple helpers now panic during setup for a non-positive request limit or window. Omit the middleware to disable it.</li></ul><h2 id="configuration-validation" tabindex="-1">Configuration Validation <a class="header-anchor" href="#configuration-validation" aria-label="Permalink to “Configuration Validation”">​</a></h2><ul><li>Encoding middleware supports <code>gzip</code> only. Empty, duplicate, or unsupported configured encodings now panic during construction instead of silently passing responses through. Eligible responses are still streamed and gzip is applied regardless of body size.</li><li>CORS wildcard/regex matching now accepts legal origins containing a port up to its documented bounded input size. <code>OnOriginTooLong</code> can observe requests rejected for exceeding that bound; ordinary policy denials remain unchanged.</li><li><code>securecookie.DefaultMaxLength</code> is an encoded-value budget, not a 4 KiB application-payload budget. The default leaves roughly 2.2 KiB for the tested session-shaped value. Use <code>CookieStore.MaxLength</code> or <code>Codec.SetMaxLength</code> at setup time when a different budget is required, while accounting for the complete cookie name and attributes in browser limits.</li></ul><h2 id="path-normalization-is-not-performed" tabindex="-1">Path Normalization Is Not Performed <a class="header-anchor" href="#path-normalization-is-not-performed" aria-label="Permalink to “Path Normalization Is Not Performed”">​</a></h2><p>Unlike <code>net/http.ServeMux</code>, Ada matches the decoded <code>r.URL.Path</code> verbatim: no <code>path.Clean</code>, no canonicalizing redirect. This is intentional and is <strong>not</strong> going to change — but it moves normalization into your handlers.</p><ul><li>Every <code>r.PathValue</code> result is attacker-controlled. Greedy captures (<code>*</code>, <code>{name...}</code>) can contain <code>..</code>, <code>.</code>, and empty segments, whether sent literally (<code>/static/../../etc/passwd</code>) or percent-encoded (<code>/static/..%2f..%2fetc/passwd</code>) — both decode to the same value before matching.</li><li>Clean and confine any captured value before using it as a filesystem path. Prefer <code>os.OpenRoot</code>/<code>fs.FS</code> or the <a href="./handler/folder.html"><code>handler/folder</code></a> handler over <code>filepath.Join</code> on raw input.</li><li><code>%2F</code> in a request decodes to a real separator, so a single-segment <code>{name}</code> param can never capture a slash: <code>GET /users/a%2Fb</code> is matched as <code>/users/a/b</code> and 404s. Carry such identifiers in a query parameter, the body, or a slash-free encoding.</li></ul><p>See <a href="./routing.html#path-handling">Path handling and captured values</a> for details and a safe file-serving pattern.</p>',23)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
